+
+/**
+ * Tests for OpenPGP unobtrusive signed message composition.
+ *
+ * Derived from browser_sendFormat.js and browser_composeSigned.js
+ */
+
+"use strict";
+
+const { getMimeTree } = ChromeUtils.importESModule(
